from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode

def apply_rewrite_rules(rules, urls):
    results = []

    for url_str in urls:
        parsed = urlparse(url_str)
        matched = False

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            # --- 1. 条件判定 (Match) ---
            is_matched = False

            if match_type == "path_prefix":
                # パスが match_value で始まるか
                if parsed.path.startswith(match_value):
                    is_matched = True

            elif match_type == "host":
                host = parsed.hostname or ""
                if match_value.startswith("*."):
                    suffix = match_value[2:]  # 例: "*.example.com" -> "example.com"
                    # サブドメインの判定（ドメインそのものは除外、厳密なサブドメイン）
                    if host.endswith("." + suffix) and host != suffix:
                        is_matched = True
                else:
                    if host == match_value:
                        is_matched = True

            elif match_type == "query_param":
                # クエリパラメータに match_value という名前が存在するか
                query_params = parse_qsl(parsed.query, keep_blank_values=True)
                if any(k == match_value for k, v in query_params):
                    is_matched = True

            # --- 2. アクション実行 (Action) ---
            if is_matched:
                matched = True

                # アクションが "block" の場合は None を返す
                if action == "block":
                    results.append(None)
                    break

                elif action == "strip_prefix":
                    # パスの先頭から action_value を削除
                    if parsed.path.startswith(action_value):
                        new_path = parsed.path[len(action_value):]
                        if not new_path:
                            new_path = "/"
                        parsed = parsed._replace(path=new_path)
                    results.append(urlunparse(parsed))
                    break

                elif action == "redirect_host":
                    # ホストを action_value に置き換える
                    # ポート番号が含まれている可能性を考慮し、ネットロック（netloc）を適切に再構築
                    old_netloc = parsed.netloc
                    if "@" in old_netloc:
                        user_info, _ = old_netloc.rsplit("@", 1)
                        user_info += "@"
                    else:
                        user_info = ""

                    if ":" in parsed.netloc and not parsed.netloc.endswith("]"):
                        # IPv6アドレスまたはポート番号がある場合簡易処理
                        # ここでは単純にポートを保持するロジックを追加
                        parts = parsed.netloc.split(":")
                        # IPv6のブラケット考慮など厳密には必要だが、簡易的にポート分離
                        if len(parts) > 1 and not parts[-1].isalpha():
                            port = parts[-1]
                            new_netloc = f"{user_info}{action_value}:{port}"
                        else:
                            new_netloc = f"{user_info}{action_value}"
                    else:
                        # ポートがない場合
                        # netlocからポート部分を抽出
                        if ":" in parsed.netloc:
                            host_part, port_part = parsed.netloc.rsplit(":", 1)
                            new_netloc = f"{user_info}{action_value}:{port_part}"
                        else:
                            new_netloc = f"{user_info}{action_value}"

                    parsed = parsed._replace(netloc=new_netloc)
                    results.append(urlunparse(parsed))
                    break

                elif action == "add_query_param":
                    # クエリに action_value（例: "key=value" または "key=val1&val2" など）を追加
                    query_params = parse_qsl(parsed.query, keep_blank_values=True)

                    # action_Value をパースして追加
                    additional_params = parse_qsl(action_value, keep_blank_values=True)
                    query_params.extend(additional_params)

                    new_query = urlencode(query_params)
                    parsed = parsed._replace(query=new_query)
                    results.append(urlunparse(parsed))
                    break

        # どのルールにも適合しなかった場合
        if not matched:
            results.append(url_str)

    return results
